edits.newText:
bool isTrackVisible(String path) {
  final viewportContext = viewportKey.currentContext;
  final rowContext = rowKeys[path]?.currentContext;
  if (viewportContext == null || rowContext == null) return false;

  final viewportBox = viewportContext.findRenderObject();
  final rowBox = rowContext.findRenderObject();
  if (viewportBox is! RenderBox || rowBox is! RenderBox) return false;
  if (!viewportBox.hasSize || !rowBox.hasSize) return false;

  final viewportRect = viewportBox.localToGlobal(Offset.zero) &
      viewportBox.size;
  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;

  const epsilon = 0.5;
  final completelyOutside =
      rowRect.bottom <= viewportRect.top + epsilon ||
      rowRect.top >= viewportRect.bottom - epsilon;
  return !completelyOutside;
}

// Register the scroll-to-track + visibility implementation onto the passed
// handle; clear them on dispose / handle swap so a stale browser never
// answers a call.
useEffect(() {
  browserController?._scrollToTrack = scrollToTrack;
  browserController?._isTrackVisible = isTrackVisible;
  return () {
    browserController?._scrollToTrack = null;
    browserController?._isTrackVisible = null;
  };
}, [browserController]);

// Coalesce scroll events so parents can recompute visibility UI.
useEffect(() {
  if (browserController == null) return null;

  Timer? t;
  void onScroll() {
    t?.cancel();
    t = Timer(const Duration(milliseconds: 40), () {
      if (!context.mounted) return;
      browserController!.scrollVisibilityTick.value++;
    });
  }

  scroll.addListener(onScroll);
  return () {
    scroll.removeListener(onScroll);
    t?.cancel();
  };
}, [browserController]);

